infra/main.tf.after:
locals {
  buckets = ["logs", "reports"]
  tags    = { team = "platform" }
}

data "aws_iam_policy_document" "reader" {
  dynamic "statement" {
    for_each = local.buckets
    content {
      effect    = "Allow"
      actions   = ["s3:GetObject", "s3:ListBucket"]
      resources = [
        "arn:aws:s3:::${statement.value}",
        "arn:aws:s3:::${statement.value}/*",
      ]
    }
  }

  statement {
    effect    = "Allow"
    actions   = ["ec2:DescribeInstances"]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "reader" {
  name   = var.enabled ? "reader" : "reader-off"
  policy = data.aws_iam_policy_document.reader.json
  tags   = { for k, v in local.tags : lower(k) => v }
}

resource "aws_instance" "web" {
  ami           = var.ami
  instance_type = "t3.micro"
  user_data     = <<-EOT
    #!/bin/bash
    echo "effect of the change: none" > /etc/motd
    echo "principal host: $(hostname)" >> /etc/motd
  EOT
}

infra/msg.tf.after:
variable "greeting" {
  default = "statement: %{ if var.prod }production%{ else }staging%{ endif }"
}

output "msg" {
  value = "the statement is %{ if var.prod }live%{ endif }"
}
